insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('0cb86eba-a247-5e28-bc2d-81ab9816c97e','2805e0b4-0413-5bc8-b056-b24275a0d717','69191203-eea3-5ba3-8329-7ad0ff247d49',1,'single_choice','본 과제 해결에 알맞은 알고리즘의 유형을 고르시오. (1) 분류모형 (2) 회귀모형 (3) 군집모형 (4) 시계열모형',5.33,2,array['문제 유형 판단']::text[],'본 과제는 호러장르 선호여부를 예측하기 위한 모델링을 수행할 것이므로, 범주형 데이터의 결과값을 가집니다. 이에 범주형 데이터 예측 문제를 해결하기 위한 분류모형이 적절합니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
