insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('21e6d5dc-a70e-54d7-a45b-213e38ed2d3c','2805e0b4-0413-5bc8-b056-b24275a0d717','72bfc91e-fd69-5249-b29c-4a0476cf10fe',2,'single_choice','다음의 범주형 변수 중 결측치(missing)가 가장 많은 변수를 고르시오. (1) 호러장르 선호여부(label_horror) (2) 연령그룹(age_group) (3) 고객 유형(customer_type) (4) 성별(sex)',6.0,2,array['결측치 탐색']::text[],'변수가 결측치를 포함하는지 여부는 데이터 분석-기초정보분석 메뉴에서 데이터 범위를 전체(7,907) 로 설정하여 조회한 후, 기술통계 영역의 missing 값으로 확인 가능합니다. 주어진 데이터에서 missing 값이 가장 큰 변수는 ‘연령그룹(age_group)’으로, 20개의 결측치가 존재합니다. 다른 변수 는 missing = 0 으로, 결측치가 존재하지 않습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
