insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('224da8e3-5525-58e3-9adf-851e33ae2ab5','2805e0b4-0413-5bc8-b056-b24275a0d717','72bfc91e-fd69-5249-b29c-4a0476cf10fe',4,'single_choice','''총 콘텐츠 구매건수(total_buy_ol)''의 기술통계량을 확인하고, 가장 큰 값을 지니는 통계량을 고르시 오. (1) 평균값 (2) 중위수 (3) 표준편차 (4) 제3사분위수',6.0,2,array['기초통계']::text[],'데이터 분석-기초정보분석 메뉴에서 ''총 콘텐츠 구매건수(total_buy_ol)'' 변수의 각 기술통계량의 값 을 확인합니다. 평균값(mean)은 ‘2.2’, 중위수(median)은 ‘1.00’, 표준편차(sd)는 ‘3.13’, 제3사분위 수(Q3)는 ‘3.00’으로, 보기 중 가장 큰 값을 지니는 통계량은 표준편차(sd) 임을 확인할 수 있습니 다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
