insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('9339b1fb-38c0-5235-ade4-17ee1a20a374','2805e0b4-0413-5bc8-b056-b24275a0d717','72bfc91e-fd69-5249-b29c-4a0476cf10fe',5,'single_choice','''총 콘텐츠 구매금액(total_amount)''과 가장 큰 양의 상관관계를 갖는 변수를 고르시오. (1) 액션 구매금액(action_amount) (2) 드라마 구매금액(drama_amount) (3) 멜로 구매금액(romc_amount) (4) 코미디 구매금액(comedy_amount)',6.0,2,array['상관관계']::text[],'변수 간 상관관계에 대한 분석은 데이터 분석-시각화 분석에서 시각화 선택 ‘히트맵’ 시각화 기법에서 전체 데이터를 조회하여 확인 가능합니다. 붉은색은 양의 상관관계, 파란색은 음의 상관관계를 의미하 며, 색의 진하기가 진할수록 상관관계가 크고, 연할수록 상관관계가 작습니다. 또한, 마우스를 오버랩 하여 상관관계의 크기인 상관계수(z)를 확인할 수 있습니다. ''총 콘텐츠 구매금액(total_amount)''에 서 가장 큰 양의 상관관계를 갖는 변수는 ‘드라마 구매금액(drama_amount)’ 임을 확인할 수 있으 며, 상관계수(z)는 0.2910027 입니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
