insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('a249f458-6561-582c-a8b3-d18b75417070','2805e0b4-0413-5bc8-b056-b24275a0d717','72bfc91e-fd69-5249-b29c-4a0476cf10fe',6,'integer','''멜로 구매금액(romc_amount)''이 ''0~100''에 속하는 고객 중 ''성별(sex)''이 ''F(여성)''인 고객의 수 를 작성하시오.',6.0,2,array['데이터 이해']::text[],'데이터 분석-시각화 분석에서 시각화 선택 ‘분포차트’ 시각화 기법을 통해 수치형 변수의 분포를 확인 할 수 있습니다. Hue 컬럼의 색상으로 표현할 범주형 변수를 지정하면, 수치형 변수의 각 구간에서 범주형 변수의 각 범주들이 얼마나 해당하는지를 확인할 수 있습니다. 문제에서 제시한 ‘멜로 구매금 액(romc_amount)''이 ''0~100''에 속하는 고객 중 ''성별(sex)''이 ''F(여성)''인 고객은 붉은색으로 확 인할 수 있고, 해당하는 고객의 수는 3345임을 확인할 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('a249f458-6561-582c-a8b3-d18b75417070','exact',null,'3345',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('29e335e9-7aab-5777-9538-14aa5abe27e7','2805e0b4-0413-5bc8-b056-b24275a0d717','06104f1d-289a-5fb9-a82b-a1c777de1dd2',7,'percentage','종속변수를 제외한 모든 변수에 대해 결측치가 있는 경우, 수치형 변수는 중앙값, 범주형 변수는 최 빈값으로 결측치를 대체하시오. 데이터 가공 후, 변화된 ''연령그룹(age_group)''의 최빈값의 비율(%)을 작성 하시오. ㅇ 수치형 변수 : "total_buy_ol", "total_amount", "action_amount", "drama_amount", "romc_amount", "comedy_amount", "horror_amount" ㅇ 범주형 변수 : "label_horror", "age_group", "customer_type", "sex" ㅇ 수행 후 [가공 데이터 저장]을 클릭하여 가공된 데이터를 저장하시오. ㅇ 00.00 형식으로 작성하시오. 예시) 12.34',30.0,2,array['결측치 처리']::text[],'데이터에 결측치가 존재하는 경우, “데이터 가공”탭을 통해 원하는 컬럼을 선택한 후 결측치 데이터를 특정 값으로 대체할 수 있습니다. 컬럼별 통계 정보를 확인하면, ‘연령그룹(age_group)’ 컬럼에서만 missing(결측치)값이 존재하는 것을 확인할 수 있습니다. ‘연령그룹(age_group)’ 컬럼은 범주형 변 수임에 따라, 해당 컬럼의 결측값 처리는 최빈값(most_frequent)으로 설정하여 변경 처리합니다. 결측치가 대체된 age_group_IM 컬럼의 기술통계랑을 확인하면, 최빈값인 ‘A07’의 비율인 Count(%) 값은 15.96 임을 확인할 수 있습니다. 마지막으로 데이터 가공과 결과값 확인이 끝났다 면 하단의 ‘가공 데이터 저장’ 버튼을 클릭하여 결과값을 저장해주시면 됩니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('29e335e9-7aab-5777-9538-14aa5abe27e7','rounded',null,'15.96',2,0.01) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('f380e66c-5647-5689-890c-8891eb06c87d','2805e0b4-0413-5bc8-b056-b24275a0d717','69191203-eea3-5ba3-8329-7ad0ff247d49',8,'single_choice','3개의 머신러닝 모델을 다음과 같은 설정으로 학습하고, 이 중 Accuracy 기준 성능이 평균적으로 가장 좋은 것을 고르시오. ㅇ 작업 데이터 선택 - 문항 7번의 데이터 가공을 통해 신규로 저장된 데이터 사용, 별도의 스케일링 처리 불필요. ㅇ 학습 유형 - 본 과제 해결에 알맞은 알고리즘의 유형을 고려하여 선택 ㅇ ML 모델 선택 - KNN, Decision Tree, Random Forest ㅇ Input 컬럼 - 문항 7번의 결측치 처리에 사용된 ''변환하기 전의 변수''는 제외 컬럼으로 지정 ㅇ Output 컬럼 - "종속 변수"를 output 컬럼으로 지정 ㅇ Data Parameter 설정 - 데이터 유형은 모델 유형에 맞게 설정하고, 나머지는 초기 설정값 사용 ㅇ 모델 Parameter 설정 - 초기 설정값 사용 (1) KNN (2) Decision Tree (3) Random Forest',5.33,2,array['문제 유형 판단','머신러닝','모델 평가 지표']::text[],'주어진 데이터를 활용하여, AI 모델 학습-머신러닝 학습 메뉴에서 머신러닝 모델 학습을 수행할 수 있 습니다. 문제에서 주어진 조건에 따라 작업 데이터 선택, 컬럼 및 파라미터를 설정하고, 3개의 머신러 닝 모델(K-Nearest Neighbor, Decision Tree, Random Forest)을 선택하여 학습을 시작하면, 일 정 시간이 경과되어 학습이 완료된 후 우측 학습결과 영역에서 각 모델별 평가 지표들을 확인할 수 있습니다. Accuracy 기준으로 성능이 가장 좋은 모델은 K-Nearest Neighbor 인 것을 확인할 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
