insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('394d95ab-b05b-5546-9bbe-d94c0e40520e','2805e0b4-0413-5bc8-b056-b24275a0d717','69191203-eea3-5ba3-8329-7ad0ff247d49',9,'decimal','딥러닝 모델을 다음과 같은 설정으로 학습하고, 학습된 모델의 Accuracy를 작성하시오. ㅇ 작업 데이터 선택 - 문항 7번의 데이터 가공을 통해 신규로 저장된 데이터 사용, 별도의 스케일링 처리 불필요 ㅇ Output 컬럼 - "종속 변수"를 output 컬럼으로 지정 ㅇ Input 컬럼 - 문항 7번의 결측치 처리에 사용된 ''변환하기 전의 변수''는 제외 컬럼으로 지정 - 범주형 변수는 데이터 인코더를 sparse로 변경 ㅇ 컬럼 Parameter 설정 - 종속변수의 데이터 유형은 모델 유형에 맞게 설정 - 활성함수: softmax, FC레이어수: 1, FC레이어크기: 256, 드롭아웃: 0.5 ㅇ 학습 Parameter 설정 - Epochs: 10, Batch Size: 256, 그 외 초기 설정값 사용 ㅇ 답안 작성 - 모델 학습 후 오른쪽 상단의 [모델 저장] 기능을 통해 모델을 저장하시오. - 정답은 반올림하여 소수점 네 번째 자리까지 작성하시오.',5.34,2,array['딥러닝','모델 평가 지표']::text[],'주어진 데이터를 활용하여, AI 모델 학습-딥러닝 학습 메뉴에서 딥러닝 모델 학습을 수행할 수 있습니 다. 문제에서 주어진 조건에 따라 작업 데이터 선택, 컬럼 및 파라미터를 설정하고 학습을 수행하면, 일정 시간이 경과되어 학습이 완료된 후 우측 학습결과 영역에서 만들어진 모델의 정확도(Accuracy) 를 확인할 수 있습니다. 생성한 모델이 ‘호러장르 선호여부(label_horror)’를 예측함에 대한 학습 정 확도(Accuracy)는 0.9358(반올림 후 소수점 네 번째 자리까지 작성) 임을 확인할 수 있습니다. 마 지막으로 오른쪽 상단의 [모델 저장] 기능을 통해 모델을 저장해주시면 됩니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('394d95ab-b05b-5546-9bbe-d94c0e40520e','absolute_tolerance',null,'0.9358',4,0.0005) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('b76716ee-099d-5416-b47d-35079443470b','2805e0b4-0413-5bc8-b056-b24275a0d717','9bddf54b-e32e-5899-80f1-18c1f3fdc02c',10,'single_choice','문항 9번에서 학습한 딥러닝 모델 분석 결과, ''호러장르 선호여부(label_horror)'' 예측에 영향을 주 는 상위 5개의 변수에 해당하지 않는 변수를 고르시오. (1) 총 콘텐츠 구매금액(total_amount) (2) 액션 구매금액(action_amount) (3) 드라마 구매금액(drama_amount) (4) 호러 구매금액(horror_amount)',8.0,2,array['변수 영향도']::text[],'생성한 모델에 대한 다양한 활용을 “AI모델 활용”을 통해 수행할 수 있습니다. 작업 데이터는 전처리 한 데이터로 선택하고, 학습하여 저장한 모델을 선택한 뒤 “변수 영향도 확인”을 선택하면, 생성한 모 델이 출력변수인 ''호러장르 선호여부(label_horror)''를 예측하는데 영향을 주는 상위 5개 변수를 확 인할 수 있습니다. 문제에서 제시한 보기 중, 상위 5개 변수에 해당하지 않는 변수는 ‘드라마 구매금 액(drama_amount)’ 임을 확인할 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
