insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('be109500-5441-5fbb-8e79-3503765d6a4b','c2458205-0894-58c0-ad05-49f1c93ed221','fb7f60fd-94c5-5a50-b7c6-785c9322e87e',1,'single_choice','본 과제 해결에 알맞은 알고리즘의 유형을 고르시오. (1) 분류모형 (2) 회귀모형 (3) 군집모형 (4) 시계열모형',7.02,2,array['문제 유형 판단']::text[],'본 과제는 호러장르 선호여부를 예측하기 위한 모델링을 수행할 것이므로, 범주형 데이터의 결 과값을 가집니다. 이에 범주형 데이터 예측 문제를 해결하기 위한 분류모형이 적절합니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
