insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('acfeff29-188f-51f4-bd34-64fee3f8c103','c2458205-0894-58c0-ad05-49f1c93ed221','f0c36728-fd90-5b2b-93fa-222761634d84',5,'single_choice','''멜로 구매금액(romc_amount)''과 가장 큰 양의 상관관계를 갖는 변수를 고르시오. (1) 총 콘텐츠 구매건수(total_buy_ol) (2) 총 콘텐츠 구매금액(total_amount) (3) 코미디 구매금액(comedy_amount) (4) 호러 구매금액(horror_amount)',3.59,2,array['상관관계']::text[],'변수 간 상관관계에 대한 분석은 데이터 분석-시각화 분석에서 시각화 선택 ‘히트맵’ 시각화 기법에서 전체 데이터를 조회하여 확인 가능합니다. 붉은색은 양의 상관관계, 파란색은 음의 상관관계를 의미하 며, 색의 진하기가 진할수록 상관관계가 크고, 연할수록 상관관계가 작습니다. 또한, 마우스를 오버랩 하여 상관관계의 크기인 상관계수(z)를 확인할 수 있습니다. ''멜로 구매금액(romc_amount)''과 가장 큰 양의 상관관계를 갖는 변수는 ‘총 콘텐츠 구매건수(total_buy_ol)’ 임을 확인할 수 있으며, 상관 계수(z)는 0.1862946 입니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
