insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('3087b17b-1344-549b-a10e-2027168ad686','c2458205-0894-58c0-ad05-49f1c93ed221','f0c36728-fd90-5b2b-93fa-222761634d84',7,'single_choice','''호러장르 선호여부(label_horror)''가 Y인 사람의 ''총 콘텐츠 구매금액(total_amount)''의 중앙값을 구하시오. (1) 1000 (2) 2500 (3) 4200 (4) 5500',3.59,2,array['기초통계']::text[],'본 문제에서 주어진 박스차트를 활용하기 위해서는 왼쪽 블레이드에 데이터 분석- 시각화 분석을 선 택 후, 시각화 선택 – 박스차트를 선택합니다. 이후, ‘호러장르 선호여부(label_horror)’에 따른 ‘총 콘텐츠 구매금액(total_amount)’의 중앙값을 구하기 위해 아래와 같이 X컬럼/Y컬럼/Hue컬럼)/데이터 범위를 선택합니다. X 컬럼 선택 : label_horror Y 컬럼 선택 : total_amount Hue 컬럼 선택 : label_horror(선택사항)_색 표현을 위함 데이터 범위 : 7907(전범위) 박스차트 결과가 나오면 확대를 진행하고 커서를 대어 값을 확인할 수 있습니다. Y의 박스차트를 확인해보면 중앙값(median)은 4,200이라는 것을 알 수 있습니다. (참고로 N의 박스차트 중앙값은 5,500입니다.)',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
