insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('3087b17b-1344-549b-a10e-2027168ad686','exact','2cac5e83-2477-53c0-b444-ad35139712c6',null,null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('bd18452b-0205-57c3-9b8b-ed3db2837a9e','c2458205-0894-58c0-ad05-49f1c93ed221','f0c36728-fd90-5b2b-93fa-222761634d84',8,'integer','''호러장르 선호여부(label_horror)''가 Y인 사람의 ''호러 구매금액(horror_amount)''의 중앙값을 구 하시오.',3.59,2,array['기초통계']::text[],'본 문제에서 주어진 박스차트를 활용하기 위해서는 왼쪽 블레이드에 데이터 분석- 시각화 분석을 선 택 후, 시각화 선택 – 박스차트를 선택합니다. 이후, ''박스차트를 활용하여 ‘호러장르 선호여부(label_horror)’가 Y인 사람의 ‘호러 구매금액 (horror_amount)’의 중앙값을 구하기 위해 아래와 같이 X컬럼/Y컬럼/Hue컬럼)/데이터 범위를 선 택합니다. X 컬럼 선택 : label_horror Y 컬럼 선택 : horror_amount Hue 컬럼 선택: label_horror(선택사항)_색 표현을 위함 데이터 범위 : 7907(전범위) 박스차트 결과가 나오면 확대를 진행하고 커서를 대어 값을 확인할 수 있습니다. Y의 박스차트를 확인해보면 중앙값(median)은 2,500이라는 것을 알 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('bd18452b-0205-57c3-9b8b-ed3db2837a9e','exact',null,'2500',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('bc5bf6b1-96c4-5856-846d-a4f3c088ad88','c2458205-0894-58c0-ad05-49f1c93ed221','8f9bb95c-7349-54cf-ba33-c0f136c97da3',9,'integer','종속변수를 제외한 모든 변수에 대해 결측치가 있는 경우, 수치형 변수는 중앙값, 범주형 변수는 최 빈값으로 결측치를 대체하시오. 데이터 가공 후, 변화된 ''연령그룹(age_group)''의 최빈값의 개수를 작성하시 오. ㅇ 수치형 변수 : "total_buy_ol", "total_amount", "action_amount", "drama_amount", "romc_amount", "comedy_amount", "horror_amount" ㅇ 범주형 변수 : "label_horror", "age_group", "customer_type", "sex" ㅇ 수행 후 [가공 데이터 저장]을 클릭하여 가공된 데이터를 저장하시오. ㅇ 0000 형식으로 작성하시오. 예시) 1234',39.47,2,array['결측치 처리']::text[],'데이터에 결측치가 존재하는 경우, “데이터 가공”탭을 통해 원하는 컬럼을 선택한 후 결측치 데이터를 특정 값으로 대체할 수 있습니다. 컬럼별 통계 정보를 확인하면, ‘연령그룹(age_group)’ 컬럼에서만 missing(결측치)값이 존재하는 것을 확인할 수 있습니다. ‘연령그룹(age_group)’ 컬럼은 범주형 변 수임에 따라, 해당 컬럼의 결측값 처리는 최빈값(most_frequent)으로 설정하여 변경 처리합니다. 결측치가 대체된 age_group_IM 컬럼의 기술통계랑을 확인하면, 최빈값인 ‘A07’의 개수는 1262 임 을 확인할 수 있습니다. 마지막으로 데이터 가공과 결과값 확인이 끝났다면 하단의 ‘가공 데이터 저장’ 버튼을 클릭하여 결과값을 저장해주시면 됩니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('bc5bf6b1-96c4-5856-846d-a4f3c088ad88','exact',null,'1262',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('f9fa64ae-42e9-5bba-8af6-f52ce3d194d8','c2458205-0894-58c0-ad05-49f1c93ed221','f0c36728-fd90-5b2b-93fa-222761634d84',10,'integer','''연령그룹(age_group_IM)'' 별 ''드라마 구매금액(drama_amount)''을 시각화하고, '' 연령그룹 (age_group_IM)'' A15의 IQR의 Q3 값을 작성하시오. ㅇ 작업 데이터 선택 - 문항 9번의 데이터 가공을 통해 신규로 저장된 데이터 사용, 별도의 스케일링 처리 불필요.',3.59,2,array['이상치','시각화']::text[],'데이터분석-시각화 분석 메뉴에서 박스차트를 활용하여 사분범위를 확인할 수 있습니다. 문제에서 주 어진 조건에 따라 X컬럼과 Y컬럼을 선택하고, 작업 데이터 범위를 전체로 설정하여 조회합니다. 우 측 시각화 결과 영역의 박스차트에서 X컬럼별 ‘드라마 구매금액(drama_amount)’ 값의 분포를 확 인할 수 있습니다. 문제에서 요청한 ‘연령그룹(age_group_IM)’ A15에 커서를 두면, A15의 Q3(삼분위수)는 7750임을 확인할 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('f9fa64ae-42e9-5bba-8af6-f52ce3d194d8','exact',null,'7750',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('f4d77198-a9a8-5d14-beda-4f4b6e0fd5ee','c2458205-0894-58c0-ad05-49f1c93ed221','f0c36728-fd90-5b2b-93fa-222761634d84',11,'integer','''연령그룹(age_group_IM)'' 별 ''드라마 구매금액(drama_amount)''을 시각화하고, ''연령그룹 (age_group_IM)'' A04의 이상치 중 가장 작은 값을 작성하시오. ㅇ 작업 데이터 선택 - 문항 9번의 데이터 가공을 통해 신규로 저장된 데이터 사용, 별도의 스케일링 처리 불필요',3.59,2,array['이상치','시각화']::text[],'데이터분석-시각화 분석 메뉴에서 박스차트를 활용하여 사분범위와 이상치를 확인할 수 있습니다. 문 제에서 주어진 조건에 따라 X컬럼과 Y컬럼을 선택하고, 작업 데이터 범위를 전체로 설정하여 조회합 니다. 우측 시각화 결과 영역의 박스차트에서 X컬럼별 IQR과 이상치 분포를 확인할 수 있습니다. 문제에서 요청한 ‘연령그룹(age_group_IM)’ A04에 커서를 두면, A04의 Upper fence*는 5000. Upper fence를 벗어난 이상치 중 최소값은 6400임을 확인할 수 있습니다. *Upper fence(이상치 식별을 위한 상단 경계) = Q3 + 1.5*IQR',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('f4d77198-a9a8-5d14-beda-4f4b6e0fd5ee','exact',null,'6400',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('a0d123d6-924f-5dd8-ad65-69564d60d018','c2458205-0894-58c0-ad05-49f1c93ed221','f0c36728-fd90-5b2b-93fa-222761634d84',12,'unit_value',''' 고객 유형(customer_type)'' 별 ''드라마 구매금액(drama_amount)''을 시각화하고, ‘고객 유형 (customer_type) ‘ 공공기관의 이상치 중 가장 작은 값을 작성하시오. ㅇ 정답은 00.0k 형식으로 작성하시오. 예시) 22.3k',3.59,2,array['이상치','시각화']::text[],'데이터분석-시각화 분석 메뉴에서 박스차트를 활용하여 사분범위와 이상치를 확인할 수 있습니다. 문 제에서 주어진 조건에 따라 X컬럼과 Y컬럼을 선택하고, 작업 데이터 범위를 전체로 설정하여 조회합 니다. 우측 시각화 결과 영역의 박스차트에서 X컬럼별 IQR과 이상치 분포를 확인할 수 있습니다. 문제에서 요청한 ‘고객 유형(customer_type) 공공기관''에 커서를 두면, 공공기관의 Upper fence 는 10k. Upper fence를 벗어난 이상치 중 최소값은 12.9k임을 확인할 수 있습니다. *Upper fence(이상치 식별을 위한 상단 경계) = Q3 + 1.5*IQR',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('a0d123d6-924f-5dd8-ad65-69564d60d018','exact',null,'12.9k',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('53418848-2e27-5b54-aedf-08602b00ec36','c2458205-0894-58c0-ad05-49f1c93ed221','f0c36728-fd90-5b2b-93fa-222761634d84',13,'integer','''멜로 구매금액(romc_amount)''이 ''0~100''에 속하는 고객 중 ''성별(sex)''이 ''M(남성)''인 고객의 수 를 작성하시오.',3.57,2,array['데이터 이해']::text[],'데이터 분석-시각화 분석에서 시각화 선택 ‘분포차트’ 시각화 기법을 통해 수치형 변수의 분포를 확인 할 수 있습니다. Hue 컬럼의 색상으로 표현할 범주형 변수를 지정하면, 수치형 변수의 각 구간에서 범주형 변수의 각 범주들이 얼마나 해당하는지를 확인할 수 있습니다. 문제에서 제시한 ''멜로 구매금 액(romc_amount)''이 ''0~100''에 속하는 고객 중 ''성별(sex)''이 ''M(남성)''인 고객은 파란색으로 확 인할 수 있고, 해당하는 고객의 수는 3294임을 확인할 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('53418848-2e27-5b54-aedf-08602b00ec36','exact',null,'3294',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('3d5a3a8e-c95e-503c-b529-d40f9f59bdeb','c2458205-0894-58c0-ad05-49f1c93ed221','fb7f60fd-94c5-5a50-b7c6-785c9322e87e',14,'decimal','머신러닝 모델을 다음과 같은 설정으로 학습하고, Random Forest의 재현율(Recall)을 작성하시 오. ㅇ 작업 데이터 선택 - 문항 9번 데이터 가공을 통해 신규 저장된 데이터 사용, 별도 스케일링 처리 불필요 ㅇ 학습 유형 - 본 과제 해결에 알맞은 알고리즘의 유형을 고려하여 선택 ㅇ ML. 모델 선택 - KNN, Decision Tree, Random Forest ㅇ Output 컬럼 - "종속 변수"를 output 컬럼으로 지정 ㅇ Input 컬럼 - 문항 9번의 결측치 처리에 사용된 ''변환하기 전의 변수''는 제외 컬럼으로 지정 ㅇ Data Parameter 설정 - 데이터 유형은 모델 유형에 맞게 설정하고, 나머지는 초기 설정값 사용 ㅇ 모델 Parameter 설정 - 초기 설정값 사용',7.02,2,array['문제 유형 판단','머신러닝','모델 평가 지표']::text[],'주어진 데이터를 활용하여, AI 모델 학습-머신러닝 학습 메뉴에서 머신러닝 모델 학습을 수행할 수 있 습니다. 문제에서 주어진 조건에 따라 작업 데이터 선택, 컬럼 및 파라미터를 설정하고 학습을 수행하 면, 일정 시간이 경과되어 학습이 완료된 후 우측 학습결과 영역에서 만들어진 모델의 재현율(Recall) 를 확인할 수 있습니다. 생성한 모델이 ‘호러장르 선호여부(label_horror)’를 예측함에 대한 학습 정확도(Accuracy)는 0.8649 (반올림 후 소수점 네 번째 자리까지 작성)임을 확인할 수 있습니다. 마지막으로 오른쪽 상단 의 [모델 저장] 기능을 통해 모델을 저장해주시면 됩니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('3d5a3a8e-c95e-503c-b529-d40f9f59bdeb','absolute_tolerance',null,'0.8649',4,0.0005) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('8c7c6631-17ed-59f7-8d3b-32bafffc1b60','c2458205-0894-58c0-ad05-49f1c93ed221','fb7f60fd-94c5-5a50-b7c6-785c9322e87e',15,'decimal','딥러닝 모델을 다음과 같은 설정으로 학습하고, 학습된 모델의 Accuracy를 작성하시오. ㅇ 작업 데이터 선택 - 문항 9번 데이터 가공을 통해 신규 저장된 데이터 사용, 별도 스케일링 처리 불필요 ㅇ Output 컬럼 - "종속 변수"를 output 컬럼으로 지정 ㅇ Input 컬럼 - 문항 9번의 결측치 처리에 사용된 ''변환하기 전의 변수''는 제외 컬럼으로 지정 - 범주형 변수는 데이터 인코더를 sparse로 변경 ㅇ 컬럼 Parameter 설정 - 종속변수의 데이터 유형은 모델 유형에 맞게 설정 - 활성함수: softmax, FC레이어수: 1, FC레이어크기: 256, 드롭아웃: 0, ㅇ 학습 Parameter 설정 - Epochs: 20, Batch Size: 256, 그 외 초기 설정값 사용 ㅇ 답안 작성 - 모델 학습 후 오른쪽 상단의 [모델 저장] 기능을 통해 모델을 저장하시오. - 정답은 반올림하여 소수점 네 번째 자리까지 작성하시오.',7.02,2,array['딥러닝','모델 평가 지표']::text[],'주어진 데이터를 활용하여, AI 모델 학습-딥러닝 학습 메뉴에서 딥러닝 모델 학습을 수행할 수 있습니 다. 문제에서 주어진 조건에 따라 작업 데이터 선택, 컬럼 및 파라미터를 설정하고 학습을 수행하면, 일정 시간이 경과되어 학습이 완료된 후 우측 학습결과 영역에서 만들어진 모델의 정확도(Accuracy) 를 확인할 수 있습니다. 생성한 모델이 ‘호러장르 선호여부(label_horror)’를 예측함에 대한 학습 정 확도(Accuracy)는 0.9536(반올림 후 소수점 네 번째 자리까지 작성) 임을 확인할 수 있습니다. 마 지막으로 오른쪽 상단의 [모델 저장] 기능을 통해 모델을 저장해주시면 됩니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
