insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('59a9694a-efb7-58da-b9b7-9d5365aa07b1','b1a81212-7c8c-5183-ae95-9cdb96ff80c7','ac095818-ddd5-595a-982d-9ed2cb68481d',2,'single_choice','본 과제를 해결하기 위한 종속변수를 고르시오 (1) 호러장르 선호여부(label_horror) (2) 총 콘텐츠 구매건수(total_buy_ol) (3) 총 콘텐츠 구매금액(total_amount) (4) 액션 구매금액(action_amount)',3.2,2,array['모델 설정']::text[],'본 과제는 호러장르 선호여부를 예측하기 위한 모델링을 수행할 것입니다. 따라서 호러장르 선호여부 를 나타내는 ‘호러장르 선호여부(label_horror)’를 종속변수로 설정하는 것이 바람직합니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
