insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('cfcf8c18-a90e-5672-9a8b-92e0da47337e','b1a81212-7c8c-5183-ae95-9cdb96ff80c7','925ffc04-d642-5cf1-896e-5f5df6a57e03',5,'single_choice','''호러 구매금액(horror_amount)''과 가장 큰 양의 상관관계를 갖는 변수를 구하시오. (1) 총 콘텐츠 구매건수(total_buy_ol) (2) 총 콘텐츠 구매금액(total_amount) (3) 액션 구매금액(action_amount) (4) 드라마 구매금액(drama_amount)',4.29,2,array['상관관계']::text[],'변수 간 상관관계에 대한 분석은 데이터 분석-시각화 분석에서 시각화 선택 ‘히트맵’ 시각화 기법에서 전체 데이터를 조회하여 확인 가능합니다. 붉은색은 양의 상관관계, 파란색은 음의 상관관계를 의미하 며, 색의 진하기가 진할수록 상관관계가 크고, 연할수록 상관관계가 작습니다. 또한, 마우스를 오버랩 하여 상관관계의 크기인 상관계수(z)를 확인할 수 있습니다. ''호러 구매금액(horror_amount)''과 가장 큰 양의 상관관계를 갖는 변수는 ‘총 콘텐츠 구매건수(total_buy_ol)’ 임을 확인할 수 있으며, 상관계 수(z)는 0.189013 입니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
