insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('878c8237-022a-5611-beff-d787b5a9afec','b1a81212-7c8c-5183-ae95-9cdb96ff80c7','925ffc04-d642-5cf1-896e-5f5df6a57e03',7,'single_choice','‘호러장르 선호여부(label_horror)''가 ''Y''일 때, ''총 컨텐츠 구매건수(total_buy_ol)''의 이상치가 아닌 값의 상한선을 고르세요 (1) 2 (2) 4 (3) 6 (4) 8',4.29,2,array['이상치']::text[],'데이터의 이상치를 파악하기 위해서는, 데이터 분석 - 시각화 분석의 박스차트(Box plot) 를 활용할 수 있습니다. ‘호러장르 선호여부(label_horror)’가 Y인 그룹에서 ‘총 컨텐츠 구매건수(total_buy_ol) 의 이상치 정보를 파악하기 위해서, X 컬럼을 label_horror, y 컬럼을 total_buy_ol로 선택하고, 데 이터 범위를 최대로 지정하여 조회합니다. label_horror가 Y인 박스 차트에 마우스를 올려보면, 최대 치(max)와, 이상치가 아닌 값의 상한선 (upper fence), 3분위점(q3) 등의 정보를 확인할 수 있습니 다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
