insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('8d52c259-6897-545d-a534-00a5d7d969c8','b1a81212-7c8c-5183-ae95-9cdb96ff80c7','925ffc04-d642-5cf1-896e-5f5df6a57e03',8,'single_choice','''고객 유형(customer_type)''별 ''총 콘텐츠 구매건수(total_buy_ol)''를 시각화하고, ''총 콘텐츠 구매 건수(total_buy_ol)''가 ''1''건인 고객이 가장 많이 속한 ''고객 유형(customer_type)’의 구간을 고르시오. (1) 개인 (2) 개인사업자 (3) 법인사업자 (4) 공공기관',4.29,2,array['시각화']::text[],'데이터의 분포를 시각화하기 위해서는 데이터 분석 - 시각화 분석의 분포차트(Density plot) 를 활용할 수 있습니다. X 컬럼을 total_by_ol, Hue 컬럼을 customer_type으로 선택하고, 데이터 범위를 최대로 지정하여 조회합니다. 총 컨텐츠 구매건수(total_by_ol )가 ‘1’건인 고객을 자세히 확인 하기 위해, X 축 최소값과 최댓값을 적당한 값으로 지정합니다. customer_type 가 ’개인’인 유형이 가장 많은 분포를 보이는 것을 확인할 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
