insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('60cc20e7-38c2-57cd-8065-cb737eb9b12c','b1a81212-7c8c-5183-ae95-9cdb96ff80c7','925ffc04-d642-5cf1-896e-5f5df6a57e03',9,'integer','''멜로 구매금액(romc_amount)''이 ''0~100''에 속하는 고객 중 ''성별(sex)''이 ''F(여성)''인 고객의 수 를 작성하시오.',4.26,2,array['데이터 이해']::text[],'데이터 분석-시각화 분석에서 시각화 선택 ‘분포차트’ 시각화 기법을 통해 수치형 변수의 분포를 확인 할 수 있습니다. Hue 컬럼의 색상으로 표현할 범주형 변수를 지정하면, 수치형 변수의 각 구간에서 범주형 변수의 각 범주들이 얼마나 해당하는지를 확인할 수 있습니다. 문제에서 제시한 ''멜로 구매금 액(romc_amount)''이 ''0~100''에 속하는 고객 중 ''성별(sex)''이 ''F(여성)''인 고객은 붉은색으로 확 인할 수 있고, 해당하는 고객의 수는 3345임을 확인할 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('60cc20e7-38c2-57cd-8065-cb737eb9b12c','exact',null,'3345',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('69c723bf-21c3-5124-9c07-9ed75daa9118','b1a81212-7c8c-5183-ae95-9cdb96ff80c7','9a76b520-0eb4-503e-8576-34cf42257765',10,'percentage','종속변수를 제외한 모든 변수에 대해 결측치가 있는 경우, 수치형 변수는 중앙값, 범주형 변수는 최 빈값으로 결측치를 대체하시오. 데이터 가공 후, 변화된 ''연령그룹(age_group)''의 최빈값의 비율(%)을 작성 하시오. ㅇ 수치형 변수 : "total_buy_ol", "total_amount", "action_amount", "drama_amount", "romc_amount", "comedy_amount", "horror_amount" ㅇ 범주형 변수 : "label_horror", "age_group", "customer_type", "sex" ㅇ 수행 후 [가공 데이터 저장]을 클릭하여 가공된 데이터를 저장하시오. ㅇ 00.00 형식으로 작성하시오. 예시) 12.34',30.0,2,array['결측치 처리']::text[],'데이터에 결측치가 존재하는 경우, “데이터 가공”탭을 통해 원하는 컬럼을 선택한 후 결측치 데이터를 특정 값으로 대체할 수 있습니다. 컬럼별 통계 정보를 확인하면, ‘연령그룹(age_group)’ 컬럼에서만 missing(결측치)값이 존재하는 것을 확인할 수 있습니다. ‘연령그룹(age_group)’ 컬럼은 범주형 변 수임에 따라, 해당 컬럼의 결측값 처리는 최빈값(most_frequent)으로 설정하여 변경 처리합니다. 결측치가 대체된 age_group_IM 컬럼의 기술통계랑을 확인하면, 최빈값인 ‘A07’의 비율인 Count(%) 값은 15.96 임을 확인할 수 있습니다. 마지막으로 데이터 가공과 결과값 확인이 끝났다 면 하단의 ‘가공 데이터 저장’ 버튼을 클릭하여 결과값을 저장해주시면 됩니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('69c723bf-21c3-5124-9c07-9ed75daa9118','rounded',null,'15.96',2,0.01) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('d6be8b7b-455b-5254-aa51-f5b7e06d96af','b1a81212-7c8c-5183-ae95-9cdb96ff80c7','ac095818-ddd5-595a-982d-9ed2cb68481d',11,'decimal','딥러닝 모델을 다음과 같은 설정으로 학습하고, 학습된 모델의 Accuracy를 작성하시오. ㅇ 작업 데이터 선택 - 문항 10번의 데이터 가공을 통해 신규로 저장된 데이터 사용, 별도의 스케일링 처리 불필요 ㅇ Output 컬럼 - "종속 변수"를 output 컬럼으로 지정 ㅇ Input 컬럼 - 문항 10번의 결측치 처리에 사용된 ''변환하기 전의 변수''는 제외 컬럼으로 지정 - 범주형 변수는 데이터 인코더를 sparse로 변경 ㅇ 컬럼 Parameter 설정 - 종속변수의 데이터 유형은 모델 유형에 맞게 설정 - 활성함수: softmax, FC레이어수: 1, FC레이어크기: 256, 드롭아웃: 0, ㅇ 학습 Parameter 설정 - Epochs: 20, Batch Size: 256, 그 외 초기 설정값 사용 ㅇ 답안 작성 - 모델 학습 후 오른쪽 상단의 [모델 저장] 기능을 통해 모델을 저장하시오. - 정답은 반올림하여 소수점 네 번째 자리까지 작성하시오.',3.2,2,array['딥러닝','모델 평가 지표']::text[],'주어진 데이터를 활용하여, AI 모델 학습-딥러닝 학습 메뉴에서 딥러닝 모델 학습을 수행할 수 있습니 다. 문제에서 주어진 조건에 따라 작업 데이터 선택, 컬럼 및 파라미터를 설정하고 학습을 수행하면, 일정 시간이 경과되어 학습이 완료된 후 우측 학습결과 영역에서 만들어진 모델의 정확도(Accuracy) 를 확인할 수 있습니다. 생성한 모델이 ‘호러장르 선호여부(label_horror)’를 예측함에 대한 학습 정 확도(Accuracy)는 0.9536(반올림 후 소수점 네 번째 자리까지 작성) 임을 확인할 수 있습니다. 마 지막으로 오른쪽 상단의 [모델 저장] 기능을 통해 모델을 저장해주시면 됩니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('d6be8b7b-455b-5254-aa51-f5b7e06d96af','absolute_tolerance',null,'0.9536',4,0.0005) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('c3472197-14d8-52cd-8ce7-6d0f81066cd7','b1a81212-7c8c-5183-ae95-9cdb96ff80c7','1a8c0c25-72e0-5ce6-9a53-06746dc15358',12,'single_choice','문항 11번에서 학습한 딥러닝 모델 분석 결과, ''호러장르 선호여부(label_horror)'' 예측에 영향을 주 는 상위 5개의 변수에 해당하는 변수를 고르시오. (1) 코미디 구매금액(comedy_amount) (2) 드라마 구매금액(drama_amount) (3) 총 콘텐츠 구매금액(total_amount) (4) 멜로 구매금액(romc_amount)',12.0,2,array['변수 영향도']::text[],'생성한 모델에 대한 다양한 활용을 “AI모델 활용”을 통해 수행할 수 있습니다. 작업 데이터 는 전처리 한 데이터로 선택하고, 학습하여 저장한 모델을 선택한 뒤 “변수 영향도 확인”을 선택하면, 생성한 모델이 출력변수인 ''호러장르 선호여부(label_horror)''를 예측하는데 영향 을 주는 상위 5개 변수를 확인할 수 있습니다. 문제에서 제시한 보기 중, 상위 5개 변수에 해당하는 것은 총 콘텐츠 구매금액(total_amount)인 것을 알 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
