insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('c3472197-14d8-52cd-8ce7-6d0f81066cd7','exact','22e955cc-dc19-57d5-bc1b-08e8cfaba4c3',null,null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('3bc59a4f-d19a-5b22-8613-df0f8569d5a0','b1a81212-7c8c-5183-ae95-9cdb96ff80c7','1a8c0c25-72e0-5ce6-9a53-06746dc15358',13,'single_choice','문항 11번에서 학습한 딥러닝 모델을 활용하여 다음과 같은 조건일 때의 ''호러장르 선호여부 (label_horror)''를 예측하시오. ㅇ action_amount: 2500 ㅇ age_group_IM: A07 ㅇ comedy_amount: 0 ㅇ customer_type: 개인 ㅇ drama_amount: 2500 ㅇ horror_amount: 3000 ㅇ romc_amount: 0 ㅇ sex: M ㅇ total_amount: 8000 ㅇ total_buy_ol: 3 (1) Y(선호함) (2) N(선호하지 않음)',12.0,2,array['예측 시뮬레이션']::text[],'“AI모델 활용” 에서 생성한 모델에 임의의 값을 넣어 어떤 결과가 출력되는지를 시뮬레이션 해 볼 수 있습니다. “시뮬레이션”을 선택하고, 문제에서 제시하는 대로 각 변수별 값을 입력하면 우측 하단에서 시뮬레이션 결과가 도출됩니다. 주어진 입력값들에 대한 ''호러장르 선호여부(label_horror)''에 대한 예측 시뮬레이션 결과는 label_horror_predictions이며, ‘Y(선호함)’으로 예측됨을 확인할 수 있습니 다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
