insert into public.question_choices(id,question_id,label,content,sort_order) values('19d7f60e-a4a7-50c7-ace5-bef94901052b','3bc59a4f-d19a-5b22-8613-df0f8569d5a0','2','N(선호하지 않음)',2) on conflict(question_id,label) do update set content=excluded.content;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('3bc59a4f-d19a-5b22-8613-df0f8569d5a0','exact','17de3f65-1ddf-5d61-ba18-ee9e21856a0a',null,null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('3f96d47b-ad2a-56fd-9f88-5974dbc97686','b1a81212-7c8c-5183-ae95-9cdb96ff80c7','ac095818-ddd5-595a-982d-9ed2cb68481d',14,'single_choice','3개의 머신러닝 모델을 다음과 같은 설정으로 학습하고, 이 중 Precision 기준 성능이 평균적으로 가장 좋은 것을 고르시오. ㅇ 작업 데이터 선택 : 문항 10번의 데이터 가공을 통해 신규로 저장된 데이터 사용, 별도의 스케일링 처 리 불필요. ㅇ 학습 유형 : 본 과제 해결에 알맞은 알고리즘의 유형을 고려하여 선택 ㅇ ML 모델 선택 : L ogistic Regression, KNN, Random Forest ㅇ Input 컬럼 : 문항 10번의 결측치 처리에 사용된 ''변환하기 전의 변수''는 제외 컬럼으로 지정 ㅇ Output 컬럼 : "종속 변수"를 output 컬럼으로 지정 ㅇ Data Parameter 설정 : 데이터 유형은 모델 유형에 맞게 설정하고, 나머지는 초기 설정값 사용 ㅇ 모델 Parameter 설정 : 초기 설정값 사용 (1) Logistic Regression (2) KNN (3) Random Forest',3.2,2,array['문제 유형 판단','머신러닝','모델 평가 지표']::text[],'주어진 데이터를 활용하여, AI 모델 학습-머신러닝 학습 메뉴에서 머신러닝 모델 학습을 수행할 수 있 습니다. 문제에서 주어진 조건에 따라 작업 데이터 선택, 컬럼 및 파라미터를 설정하고, 3 개의 머신러 닝 모델(Logistic Regression, K-Nearest Neighbor, Random Forest)을 선택하여 학습을 시작하 면, 일정 시간이 경과되어 학습이 완료된 후 우측 학습결과 영역에서 각 모델별 평가 지표들을 확인 할 수 있습니다. Precision 기준으로 성능이 가장 좋은 모델은 K-Nearest Neighbor 인 것을 확인 할 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
