insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('3066827b-cb5c-55da-922f-fe7ed73bd5e4','c668095d-56ee-5829-9194-485d6736abcc','e67af5f3-d5c9-589d-9ecb-6c7011b06baa',1,'single_choice','본 과제 해결에 알맞은 알고리즘의 유형을 고르시오. (1) 회귀모형 (2) 분류모형 (3) 군집모형 (4) 시계열모형',5.33,2,array['문제 유형 판단']::text[],'본 과제는 다음 달 납부 예정금액을 예측하는 과제로, 수치형 데이터의 결과값을 가집니다. 이에 수치 형 데이터 예측 문제를 해결하기 위한 회귀 모형이 적절합니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
