insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('37cc4557-85ee-5d15-b78e-6c97e0aede8f','c668095d-56ee-5829-9194-485d6736abcc','9e00213a-60eb-56e5-b079-d1145af7b6b8',2,'single_choice','다음의 수치형 변수 기술통계량을 확인하고, 제3 사분위수(Q3)의 크기가 가장 작은 변수를 고르시 오. (1) 잔여약정개월수(agreement_month) (2) 부가정보1(extra_info1) (3) 부가정보2(extra_info2) (4) 이전 달 납부금액(prev_fee)',7.5,2,array['기초통계']::text[],'데이터 분석-기초정보분석 메뉴에서 “데이터 범위”를 우측 끝까지 드래그 하여 전체 데이터를 선택해주시는 것이 가장 중요합니다. 기본 설정으로 분석을 하게 되면 전체 데이터가 아닌 일부 데이터에 대한 통계가 나오 기 때문에 잘못된 분석이 될 수 있습니다. 우리의 데이터는 데이터 범위를 끝까지 선택해보면 9,000개의 데이터라는 것을 알 수 있습니다. 이 기준으 로 선택지의 4가지 변수를 차례로 분석해보겠습니다. 각 변수의 “분위수” 항목에서 “Q3”를 비교해보시면 됩 니다. 선택지 순서대로 확인해보면 19.00, 4.00, 9.00, 68022.50이고 가장 작은 값을 가지는 변수는 ‘부가정 보1(extra_info1)’ [4.00] 입니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
