insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('7a641a72-079e-51f6-8967-698cc16fb8dd','exact','13d0927e-bce0-5007-8a32-a1790ba364a5',null,null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('faaa404e-a119-58c3-8c96-40c5cf330dc3','c668095d-56ee-5829-9194-485d6736abcc','9e00213a-60eb-56e5-b079-d1145af7b6b8',5,'single_choice','각 ''고객등급(customer_class)'' 별 ''납부 예정금액(label_fee)''을 시각화하고, 제1사분위수(Q1)가 가장 낮은 ''고객등급(customer_class)''을 고르시오. (1) 일반 (2) Gold (3) Silver (4) White',7.5,2,array['시각화']::text[],'데이터 분석-시각화 분석 메뉴에서 사분위수 분석을 할 수 있는 시각화 도구는 ‘박스차트’입니다. 시각화 선 택에서 ‘박스차트’를 선택해주세요. Y컬럼에 분석 대상인 수치형 변수를 선택하고 Hue에는 세분화시켜 볼 범 주형 변수를 선택해주면 됩니다. 이 문항에서는 ‘납부 예정금액(label_fee)’이라는 수치형 변수를 ‘고객등급 (customer_class)’이라는 범주형 변수 별로 세분화시켜야 합니다. 따라서 Y 컬럼 선택에서는 ‘납부 예정금 액(label_fee)’을 고르시고 Hue 컬럼 선택에서는 ‘고객등급(customer_class)’을 고르시면 됩니다. 이때, 기 초정보분석 때와 마찬가지로 ‘데이터 범위’를 우측 끝까지 드래그 하셔서 전체 데이터(9,000개)가 선택되도 록 해주십시오. 여기까지 설정하셨으면 ‘조회하기’ 버튼을 클릭하여 박스차트 결과를 우측에서 확인할 수 있습 니다. 박스차트에서 박스의 상단은 제3사분위수(Q3), 박스의 하단은 제1사분위수(Q1) 값을 의미합니다. 각 등급 별 박스의 하단 값을 비교하면 제1사분위수(Q1)가 가장 낮은 ‘고객등급(customer_class)’이 ‘일반’임을 확인할 수 있습니다. 이때, 각 박스가 어떤 ‘고객등급(customer_class)’을 의미하는지는 우측의 색상 범례를 통해 확인할 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
