insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('dbdf93bf-408b-57fd-b725-e808b8ebfac9','661d30e5-f983-5242-9314-ad3bdc1eb93f','3c9129b8-9bf4-5835-980b-1b20892a6eff',3,'integer','''고객등급(customer_class)''이 ''VVIP''인 고객의 수를 작성하시오.',7.5,2,array['데이터 이해']::text[],'데이터 분석-기초정보분석 결과값 중에 ''고객등급(customer_class)''의 최빈값 항목을 살펴보면 범주형 변 수의 항목 별 갯수를 확인할 수 있습니다. Value가 ‘VVIP’인 것을 찾아보면 고객의 수가 719인 것을 알 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('dbdf93bf-408b-57fd-b725-e808b8ebfac9','exact',null,'719',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('a9e48f41-caa1-541f-9589-56dff83518ba','661d30e5-f983-5242-9314-ad3bdc1eb93f','3c9129b8-9bf4-5835-980b-1b20892a6eff',4,'single_choice','다음의 범주형 변수 기술통계량을 확인하고, 특정 범주에 90%이상의 데이터가 몰려 있는 변수를 고르시오. (1) 고객등급(customer_class) (2) 고객 관리수준(customer_level) (3) 서비스 구분(service_category) (4) 이전 달 납부금액(prev_fee)',7.5,2,array['기초통계']::text[],'데이터 분석-기초정보분석 결과값 중에 선택지의 3가지 변수의 최빈값 항목을 살펴보면 각 항목 별 개수뿐 만 아니라 전체 데이터 중에 차지하는 비율(Count(%))도 확인할 수 있습니다. 최빈값 항목의 첫 번째 값이 최빈값을 의미하는데 3가지 변수의 최빈값의 비율은 각각 42.54%, 64.88%, 99.98% 입니다. 따라서 특정 범주에 90%이상의 데이터가 몰려 있는 변수는 ‘서비스 구분(service_category)’ 입니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
