insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('bae9232a-f666-5861-8536-4054a6a0d9c8','exact','a738ac6d-fa7d-5a4b-a0ba-2d8a82927a56',null,null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('855f5c5e-6d04-540c-aca1-1cdb100119f0','661d30e5-f983-5242-9314-ad3bdc1eb93f','c7751ae0-2837-53b1-87f6-bf3a9f4660e6',6,'integer','종속변수를 제외한 모든 변수에 대해 결측치가 있는 경우, 수치형 변수는 중앙값, 범주형 변 수는 최빈값으로 결측치를 대체하시오. 데이터 가공 후, 변화된 ''할부여부(installment_yn)''의 최빈 값의 개수를 작성하시오. O 수치형 변수 : "label_fee", "agreement_month", "extra_info1", "extra_info2", "prev_fee" O 범주형 변수 : "installment_yn", "customer_class", "customer_level", "service_category" O 수행 후 [가공 데이터 저장]을 클릭하여 가공된 데이터를 저장하시오.',30.0,2,array['결측치 처리']::text[],'데이터 가공은 ‘데이터 가공’ 메뉴에서 진행합니다. 가공에 앞서 결측치가 있는 변수를 찾아야 하는데 요. 앞에서 다룬 기초정보분석 메뉴로 다시 돌아가서 확인하는 방법도 있지만 데이터 가공하기 메뉴 에서 각 변수를 클릭해보면 우측에 기초정보분석에서 본것과 동일한 분석결과를 확인할 수 있습니다. 결측치 개수는 ‘missing’ 값을 확인하면 되는데, 각 변수에서 ‘missing’이 0이 아닌 변수를 찾아주 시면 됩니다. 종속변수(label_fee)를 제외한 나머지 변수를 차례대로 확인해보겠습니다. 1. ‘잔여약정개월수(agreement_month)’: 수치형 변수, 결측치 100개 -> 중앙값(median)으 로 결측치 대체 2. ''할부여부(installment_yn)'': 범주형 변수, 결측치 100개 -> 최빈값(most_frequent)으로 결측치 대체 3. ‘고객등급(customer_class)’: 범주형 변수, 결측치 200개 -> 최빈값(most_frequent)으 로 결측치 대체 4. ‘이전 달 납부금액(prev_fee)’: 수치형 변수, 결측치 300개 -> 중앙값(median)으로 결측 치 대체 예를 들어 ‘할부여부(installment_yn)’의 결측치를 대체해보도록 하겠습니다. ‘할부여부 (installment_yn)’를 선택하고 ‘데이터 가공 실행’의 ‘결측값 처리’ 기능을 사용해보겠습니다. 결측값 을 처리할 수 있는 방식은 목록을 클릭해보면 most_frequent(최빈값), constant(상수값)이 있는데, 문제에서 지정해준 most_frequent(최빈값)를 선택해주면 됩니다. 결측치 처리 방식을 선택한 뒤에 는 ‘보기’ 버튼을 눌러 우측에서 결과를 확인한 뒤에 ‘적용’ 버튼을 눌러 변수에 적용까지 해주셔야 합 니다. ‘ 적용’ 버튼까지 잘 누르셨다면 좌측 변수 목록의 하단에 ‘변수명_IM’이라는 결측치가 처리된 변 수가 새로 생성된 것을 볼 수 있습니다. 이 새로운 변수를 클릭해보면 ‘missing’값이 0으로 변한 것 을 확인할 수 있습니다. 변화된 ‘installment_yn’의 최빈값의 개수는 새로 생성된 ‘installment_yn_IM’ 변수의 최빈값을 확인해주시면 되고 최빈값은 ‘N’이고 그 개수는 4611개입니 다. 마지막으로 데이터 가공과 결과값 확인이 끝났다면 하단의 ‘가공 데이터 저장’ 버튼을 클릭하여 결과 값을 저장해주시면 됩니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('855f5c5e-6d04-540c-aca1-1cdb100119f0','exact',null,'4611',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('0ce754f0-7ba5-502e-90cf-6d415b55722a','661d30e5-f983-5242-9314-ad3bdc1eb93f','9c05df6e-c57f-5182-8dad-2af1a7fe1d12',7,'single_choice','3 개의 머신러닝 모델을 다음과 같은 설정으로 학습하고, 이 중 설명력(R2)이 평균적으로 가 장 높은 모델을 선택하시오. O 작업 데이터 선택 - 문항 6번의 데이터 가공을 통해 신규로 저장된 데이터 사용, 별도의 스케일링 처리 불필요. O 학습 유형 - 본 과제 해결에 알맞은 알고리즘의 유형을 고려하여 선택 O ML 모델 선택 - Linear Regression, Decision Tree Regressor, Random Forest Regressor O Output 컬럼 - "종속 변수"를 output 컬럼으로 지정 O Input 컬럼 - 문항 4번의 정답 컬럼은 제외 컬럼으로 지정 - 문항 6번의 결측치 처리에 사용된 ''변환하기 전의 변수''는 제외 컬럼으로 지정 O Data Parameter 설정 - 종속변수의 데이터 유형은 모델 유형에 맞게 설정하고, 나머지는 초기 설정값 사용 O 모델 Parameter 설정 - 초기 설정값 사용 (1) Linear Regression (2) Decision Tree Regressor (3) Random Forest Regressor',5.33,2,array['문제 유형 판단','머신러닝','모델 평가 지표']::text[],'AI모델학습-머신러닝 메뉴로 이동합니다. 문제에서 주어진 가이드에 따라 문항6번에서 가공하고 저장한 데 이터(‘amount_processed’)를 ‘작업 데이터 선택’에서 선택합니다. 다음으로 ‘학습 유형’은 문항1번에서 확인 했듯이 Regression(회귀)를 선택합니다. 학습에 사용할 3가지 모델(Linear Regression, Decision Tree Regressor, Random Forest Regressor)을 ‘ML 모델 선택’에서 선택합니다. 종속 변수인 ‘label_fee’를 Input 컬럼 목록에서 선택하여 위쪽 방향 화살표를 클릭하여 Output 컬럼으로 옮겨줍니다. 문항 4번의 정 답(특정 범주에 90%이상의 데이터가 몰려 있는 변수)인 ‘서비스 구분(service_category)’ 변수와 문항 6 번의 결측치 처리에 사용된 ‘변환하기 전의 변수’인 ‘잔여약정개월수(agreement_month)’, '' 할부여부 (installment_yn)'', ‘고객등급(customer_clas s)’, ‘ 이전 달 납부금액(prev_fee)’을 각각 선택 후 아래쪽 방향 화살표를 클릭하여 제외 컬럼으로 옮겨줍 니다. 나머지 파라미터(parameter)는 기본값으로 놔두고 ‘학습 시작’ 버튼을 눌러줍니다. 조금 기다리면 우 측에 학습 결과가 나타나는데요. 여러 성능 평가 지표 중에 문항에서 제시한 설명력(R2)이 평균적으로 가장 높은 모델은 R2가 가장 높은 Random Forest Regressor입니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
