insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('6213113d-9d5b-5586-838a-72a6a174967f','661d30e5-f983-5242-9314-ad3bdc1eb93f','dd78ce58-c71a-5ddb-b362-0ca52cfeae42',10,'integer','문항 8번에서 학습한 딥러닝 모델을 활용하여 다음과 같은 조건일 때의 ''납부 예정금액 (label_fee)''을 예측하시오. O 입력값 - agreement_month: 18 - customer_class: Gold - customer_level: A - extra_info1: 0 - extra_info1: 0 - installment_yn_IM: Y - prev_fee: 48500 O 정답은 반올림하여 정수로 작성하시오.',8.0,2,array['예측 시뮬레이션']::text[],'AI모델활용 메뉴로 이동합니다. ‘작업 데이터 선택’에서 모델 학습에 사용한 데이터(amount_processed)를 선택하고 아래 ‘학습 모델 목록’에서는 문항8번에서 학습하고 저장한 모델을 선택합니다. 특정 입력값에 대해 결과값을 예측하기 위해서는 ‘시뮬레이션’ 기능을 사용해야 합니다. ‘시뮬레이션’ 버튼을 클릭하면 우측에서 입 력값을 기입하고 예측 결과를 확인할 수 있습니다. 문제에서 제시한 입력값을 기재하면 ''납부 예정금액 (label_fee)''의 예측값 51668을 확인할 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('6213113d-9d5b-5586-838a-72a6a174967f','exact',null,'51668',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('13fcb53b-45d6-5e4f-ad32-49055726afa5','661d30e5-f983-5242-9314-ad3bdc1eb93f','dd78ce58-c71a-5ddb-b362-0ca52cfeae42',11,'decimal','문항 8번에서 학습한 딥러닝 모델을 고도화하여 MSE를 개선하고, 그 값을 작성하시오. O 변수변환, 변수선택, 파라미터 수정 등 자율적으로 수행하시오. O 정답은 반올림하여 소수점 네 번째 자리까지 작성하시오.',8.0,2,array['성능 개선']::text[],'성능 개선의 경우 여러 가지 경우의 향상 방법이 존재합니다. 본 해설에서는 대표적인 성능 향상 방법 중 하 나인 모델의 파라미터 변경을 사용하여 진행해보려고 합니다. AI모델학습-딥러닝 메뉴로 이동합니다. "전체 데 이터의 학습 횟수를 의미하는 파라미터"는 ‘Epochs’이고 이 값을 30으로 지정하고 나머지 설정은 문항 8번 과 동일하게 지정해줍니다. 이제 ‘학습 시작’ 버튼을 눌러줍니다. 조금 기다리면 우측에 학습 결과가 나타납니 다. 학습 로그의 가장 마지막에서 모델 성능을 확인할 수 있습니다. 여러 성능 평가 지표 중에 문항에서 제시 한 MSE는 0.4787입니다. MSE는 오차이기 때문에 값이 작으면 작을수록 성능이 좋은 모델이고 앞선 문항 8번의 결과보다 성능이 개선된 모델임을 알 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
