insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('71c042a7-bc89-584b-b357-37420bf1c8bb','ab1e4ff9-1462-5d53-b28b-9688869eaf66','3287b53d-4862-5a42-9a0d-9745f5e477ba',2,'single_choice','다음의 범주형 변수 기술통계량을 확인하고, 특정 범주에 90%이상의 데이터가 몰려 있는 변수를 고르시오. (1) 고객등급(customer_class) (2) 고객 관리수준(customer_level) (3) 서비스 구분(service_category) (4) 이전 달 납부금액(prev_fee)',3.75,2,array['기초통계']::text[],'데이터 분석-기초정보분석 결과값 중에 선택지의 3가지 변수의 최빈값 항목을 살펴보면 각 항목 별 개수뿐만 아니라 전체 데이터 중에 차지하는 비율(Count(%))도 확인할 수 있습니다. 최빈값 항목의 첫 번째 값이 최빈값을 의미하는데 3가지 변수의 최빈값의 비율은 각각 42.54%, 64.88%, 99.98% 입니다. 따라서 특정 범주에 90%이상의 데이터가 몰려 있는 변수는 ‘서비스 구분 (service_category)’입니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
