insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('91ffd4a5-aa49-50b6-91ef-3e3fd64c7362','ab1e4ff9-1462-5d53-b28b-9688869eaf66','3287b53d-4862-5a42-9a0d-9745f5e477ba',3,'single_choice','종속변수에 영향을 미치지 않는 변수로 모델링시 제외해야 하는 변수를 고르시오. (1) 납부 예정금액(label_fee) (2) 잔여약정개월수(agreement_month) (3) 서비스 구분(service_category) (4) 고객등급(customer_class)',3.75,2,array['데이터 이해']::text[],'데이터 분석-기초정보분석 결과값을 조회하면, ‘ 서비스 구분(service category)’ 값의 대부분이 ‘상 품A’에 몰려있는 것을 알 수 있습니다. (99.98% 상품 A, 0.02% 상품 B) 이는 ‘서비스 구분(service category)’의 데이터 불균형이 극심한 것을 알 수 있으며, 모델 학습에 활용 시 ‘과적합’ 현상을 불러일으킬 수 있습니다. 따라서 모델 학습에 활용하지 않아도 되는 컬럼은 ‘서비스 구분(service category)’입니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
