insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('00e78505-9a47-5752-bbf4-7f8685ecc9b7','ab1e4ff9-1462-5d53-b28b-9688869eaf66','3287b53d-4862-5a42-9a0d-9745f5e477ba',4,'integer','''고객등급(customer_class)''이 ''VVIP''인 고객의 수를 작성하시오.',3.75,2,array['데이터 이해']::text[],'데이터 분석-기초정보분석 결과값 중에 ''고객등급(customer_class)''의 최빈값 항목을 살펴보면 범 주형 변수의 항목 별 갯수를 확인할 수 있습니다. Value가 ‘VVIP’인 것을 찾아보면 고객의 수가 719인 것을 알 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('00e78505-9a47-5752-bbf4-7f8685ecc9b7','exact',null,'719',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('6ab7da68-71d7-5d1b-8c56-9b6e9bb14b23','ab1e4ff9-1462-5d53-b28b-9688869eaf66','3287b53d-4862-5a42-9a0d-9745f5e477ba',5,'decimal','''고객등급(customer_class)''별 ''잔여약정개월수(agreement_month)''를 시각화하고, ''고객 등급(customer_class)이 ''VVIP''인 고객의 IQR을 작성하세요. 반올림하여 소수점 둘째자리까지 표기. 예시) 5.31',3.75,2,array['이상치','시각화']::text[],'데이터 시각화는 데이터 분석 -> 데이터 시각화 메뉴에서 진행하실 수 있습니다. 여기서 ‘시각화 선 택’ 메뉴를 둘러보시면 다양한 시각화 툴이 나오는데요, 문제를 잘 읽어보시면 IQR을 요구중인걸 알 수 있습니다. IQR을 직관적으로 파악할 수 있는 시각화 툴은 ‘박스차트’ 입니다. 문제에서는 ‘고객등급(customer_class)’별 ‘잔여약정개월수(agreement_month)’에 대해 시각화 를 요구했으므로, Hue는 ‘고객등급(customer_class)’, Y 축은 ‘잔여약정개월수 (agreement_month)’로 설정하신 뒤 데이터범위를 최대값인 ‘9000’까지 드래그 후 조회하기 버 튼을 누르면, 데이터 시각화 결과가 나옵니다. 박스차트에 나온 결과를 바탕으로 ‘VVIP’ 값의 IQR값을 확인하시면 됩니다. IQR은 3사분위수(Q3)에 서 1사분위수(Q1)를 뺀 값인데, 여기서 Q3은 20.25, Q1은 0DMFH Q3-Q1 = 20.25 - 0 = 20.25 임 을 알 수 있습니다. 따라서 정답은 20.25입니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('6ab7da68-71d7-5d1b-8c56-9b6e9bb14b23','absolute_tolerance',null,'20.25',4,0.0005) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('f98f8804-aba1-5a91-87af-cbb686887a32','ab1e4ff9-1462-5d53-b28b-9688869eaf66','3287b53d-4862-5a42-9a0d-9745f5e477ba',6,'unit_value',''' 서비스 구분(service_category)''별 ''이전 달 납부금액(prev_fee)''을 시각화하고, '' 서비스 구분(service_category)''이 ''상품A''인 고객의 이상치 중 가장 큰 값을 작성하시오. 반올림하여 소수점 둘째자리까지 표기. 예시) 50.31k',3.75,2,array['이상치','시각화']::text[],'데이터 분석-시각화 분석 메뉴에서 이상치 분석을 할 수 있는 시각화 도구는 ‘박스차트’입니다. 시각 화 선택에서 ‘박스차트’를 선택해주세요. Y컬럼에 분석 대상인 수치형 변수를 선택하고 Hue에는 세분 화시켜 볼 범주형 변수를 선택해주면 됩니다. 이 문항에서는 ‘이전 달 납부금액(prev_fee)’이라는 수 치형 변수를 ‘서비스 구분(service_category)’이라는 범주형 변수 별로 세분화시켜야 합니다. 따라 서 Y 컬럼 선택에서는 ‘이전 달 납부금액(prev_fee)’을 고르시고 Hue 컬럼 선택에서는 ‘서비스 구 분(service_category)’을 고르시면 됩니다. 이때, 기초정보분석 때와 마찬가지로 ‘데이터 범위’를 우 측 끝까지 드레그 하셔서 전체 데이터(9,000개)가 선택되도록 해주십시오. 여기까지 설정하셨으면 ‘조회하기’ 버튼을 클릭하여 박스차트 결과를 우측에서 확인할 수 있습니다. 박스차트에서 박스의 상단에 위치한 upper fence와 박스의 하단에 위치한 lower fence를 벗어난 데이터를 이상치로 판단합니다. ‘ 상품A’에 해당하는 박스차트의 upper fence를 벗어난 데이터 포인 트 중 가장 큰 값을 읽어보면 129.93k입니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('f98f8804-aba1-5a91-87af-cbb686887a32','exact',null,'129.93k',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('7e817496-71d6-5431-ac97-cf8750e271a4','ab1e4ff9-1462-5d53-b28b-9688869eaf66','3287b53d-4862-5a42-9a0d-9745f5e477ba',7,'single_choice','각 ''고객등급(customer_class)''별 ''납부 예정금액(label_fee)''을 시각화하고, 제1사분위수 (Q1)가 가장 낮은 ''고객등급(customer_class)''을 고르시오. (1) 일반 (2) Gold (3) Silver (4) White',3.75,2,array['시각화']::text[],'데이터 분석-시각화 분석 메뉴에서 사분위수 분석을 할 수 있는 시각화 도구는 ‘박스차트’입니다. 시 각화 선택에서 ‘박스차트’를 선택해주세요. Y컬럼에 분석 대상인 수치형 변수를 선택하고 Hue에는 세 분화시켜 볼 범주형 변수를 선택해주면 됩니다. 이 문항에서는 ‘납부 예정금액(label_fee)’이라는 수 치형 변수를 ‘고객등급(customer_class)’이라는 범주형 변수 별로 세분화시켜야 합니다. 따라서 Y 컬럼 선택에서는 ‘납부 예정금액(label_fee)’을 고르시고 Hue 컬럼 선택에서는 ‘고객등급 (customer_class)’을 고르시면 됩니다. 이때, 기초정보분석 때와 마찬가지로 ‘데이터 범위’를 우측 끝까지 드레그 하셔서 전체 데이터(9,000개)가 선택되도록 해주십시오. 여기까지 설정하셨으면 ‘조회 하기’ 버튼을 클릭하여 박스차트 결과를 우측에서 확인할 수 있습니다. 박스차트에서 박스의 상단은 제3사분위수(Q3), 박스의 하단은 제1사분위수(Q1) 값을 의미합니다. 각 등급 별 박스의 하단값을 비교하면 제1사분위수(Q1)가 가장 낮은 ‘고객등급(customer_class)’이 ‘일반’임을 확인할 수 있습니다. 이때, 각 박스가 어떤 ‘고객등급(customer_class)’을 의미하는지는 우측의 색상 범례를 통해 확인할 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
