insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('56948963-8f7f-5f76-b51d-466302bc5381','ab1e4ff9-1462-5d53-b28b-9688869eaf66','3287b53d-4862-5a42-9a0d-9745f5e477ba',8,'single_choice','''이전 달 납부금액(prev_fee)'' 값이 최빈값인 범위를 고르시오. (1) 28k-29.999k (2) 30k-31.999k (3) 32k-33.999k (4) 46k-47.999k',3.75,2,array['기초통계']::text[],'데이터 분석-시각화 분석 메뉴에서 데이터의 분포 분석을 할 수 있는 시각화 도구는 ‘분포차트’입니다. 시각화 선택에서 ‘분포차트’를 선택해주세요. X컬럼에 데이터 분포를 확인하고자 하는 변수를 선택하 고, Hue에는 세분화시켜 볼 범주형 변수를 선택해주면 됩니다. 이 문항에서는 ‘이전 달 납부금액 (prev_fee)’이라는 변수의 분포를 확인하여 최빈값인 범위를 확인해야 합니다. 따라서 X 컬럼 선택 에서는 ‘이전 달 납부금액(prev_fee)’을 고르시고 Hue 컬럼 선택에서는 컬럼을 고르시지 않아도 됩 니다. 이때, 기초정보분석 때와 마찬가지로 ‘데이터 범위’를 우측 끝까지 드레그 하셔서 전체 데이터 (9,000개)가 선택되도록 해주십시오. 여기까지 설정하셨으면 ‘조회하기’ 버튼을 클릭하여 분포차트 결과를 우측에서 확인할 수 있습니다. 분포차트에서 ‘이전 달 납부금액(prev_fee)’의 Y값이 가장 큰 범위를 확인해 보면 28K-29.999K 범위임을 알 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
