insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('56948963-8f7f-5f76-b51d-466302bc5381','exact','4b788e54-4d74-56a7-9f65-f041f4ab5553',null,null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('29bd504f-c857-5c61-b3a3-c88172465b86','ab1e4ff9-1462-5d53-b28b-9688869eaf66','3287b53d-4862-5a42-9a0d-9745f5e477ba',9,'integer',''' 납부 예정금액(label_fee)''이 ''62k~63.9k''에 속하는 고객 중 ''고객등급 (customer_class)''이 ''Gold''인 고객의 수를 작성하시오.',3.75,2,array['데이터 이해']::text[],'데이터 분석-시각화 분석 메뉴에서 데이터의 분포 분석을 할 수 있는 시각화 도구는 ‘분포차트’입니다. 시각화 선택에서 ‘분포차트’를 선택해주세요. X 컬럼에 데이터 분포를 확인하고자 하는 변수를 선택하 고, Hue 에는 세분화시켜 볼 범주형 변수를 선택해주면 됩니다. 이 문항에서는 ‘납부 예정금액 (label_fee)’이라는 수치형 변수를 ‘고객등급(customer_class)’이라는 범주형 변수 별로 세분화시 켜야 합니다. 따라서 X컬럼 선택에서는 ‘납부 예정금액(label_fee)’을 고르시고 Hue 컬럼 선택에서 는 ‘고객등급(customer_class)’을 고르시면 됩니다. 이때, 기초정보분석 때와 마찬가지로 ‘데이터 범위’를 우측 끝까지 드레그 하셔서 전체 데이터(9,000개)가 선택되도록 해주십시오. 여기까지 설정 하셨으면 ‘조회하기’ 버튼을 클릭하여 분포차트 결과를 우측에서 확인할 수 있습니다. ''납부 예정금액(label_fee)''이 ''62k~63.9k''에 속하는 고객 중 ''고객등급(customer_class)''이 ''Gold''인 고객의 수를 확인해야 하기 때문에 분포차트 우측 색상 범례에서 ''고객등급 (customer_class)''이 ''Gold''만 나오게 선택하면 위와 같은 분포 차트를 확인할 수 있습니다. 해당 분포차트에서 ''납부 예정금액(label_fee)''이 ''62k~63.9k''인 구간을 확인해 보면 ''고객등급 (customer_class)''이 ''Gold''인 고객 수는 119명임을 알 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('29bd504f-c857-5c61-b3a3-c88172465b86','exact',null,'119',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('a0f44a5c-ebc3-54bb-be97-026e26b435f3','ab1e4ff9-1462-5d53-b28b-9688869eaf66','894c4d77-9a93-5251-83ea-49ef88d20146',10,'decimal','종속변수를 제외한 모든 변수에 대해 결측치가 있는 경우, 수치형 변수는 평균값, 범주형 변수는 최빈값으로 결측치를 대체하시오. 데이터 가공 후, 변화된 ''잔여약정개월수 (agreement_month)''의 표준편차를 작성하시오 (소수점 둘째자리까지 작성하시오, 예시: 11.11) -수치형변수: "label_fee", "agreement_month", "extra_info1", "extra_info2", "prev_fee" -범주형변수:"installment_yn", "customer_class", "customer_level", "service_category" - 수행 후 [가공 데이터 저장]을 클릭하여 가공된 데이터를 저장하시오.',30.0,2,array['결측치 처리']::text[],'데이터 가공은 ‘데이터 가공’ 메뉴에서 진행합니다. 가공에 앞서 결측치가 있는 변수를 찾아야 하는데 요. 앞에서 다룬 기초정보분석 메뉴로 다시 돌아가서 확인하는 방법도 있지만 데이터 가공하기 메뉴 에서 각 변수를 클릭해보면 우측에 기초정보분석에서 본것과 동일한 분석결과를 확인할 수 있습니다. 결측치 개수는 ‘missing’ 값을 확인하면 되는데, 각 변수에서 ‘missing’이 0이 아닌 변수를 찾아주 시면 됩니다. 종속변수(label_fee)를 제외한 나머지 변수를 차례대로 확인해보겠습니다. 1. ‘잔여약정개월수(agreement_month)’ : 수치형 변수, 결측치 100개 -> 평균값(mean)으 로 결측치 대체 2. ''할부여부(installment_yn)'' : 범주형 변수, 결측치 100개 -> 최빈값(most_frequent)으로 결측치를 대체 3. ‘고객등급(customer_class)’ : 범주형 변수, 결측치 200개 -> 최빈값(most_frequent)으 로 결측치를 대체 4. ‘이전 달 납부금액(prev_fee)’ : 수치형 변수, 결측치 300개 -> 평균값(mean)으로 결측치 대체 예를 들어 ‘잔여약정개월수(agreement_month)’의 결측치를 대체해보도록 하겠습니다. ‘잔여약정개 월수(agreement_month)’를 선택하고 ‘데이터 가공 실행’의 ‘결측값 처리’ 기능을 사용해보겠습니 다. 결측값을 처리할 수 있는 방식은 목록을 클릭해보면 most_frequent(최빈값), median( 중간값), mean(평균값), constant(상수값)이 있는데, 문제에서 지정해준 mean(평균값)을 선택해주면 됩니다. 결측치 처리 방식을 선택한 뒤에는 ‘보기’ 버튼을 눌러 우측에서 결과를 확인한 뒤에 ‘적용’ 버튼을 눌 러 변수에 적용까지 해주셔야 합니다. ‘ 적용’ 버튼까지 잘 누르셨다면 좌측 변수 목록의 하단에 ‘agreement_month_IM’ 이라는 결측치가 처리된 변수가 새로 생성된 것을 볼 수 있습니다. 이 새 로운 변수를 클릭해보면 ‘missing’값이 0으로 변한 것을 확인할 수 있습니다. 변화된 ‘잔여약정개월 수(agreement_month)’의 표준편차(sd)는 새로 생성된 ‘agreement_month_IM’ 변수의 표준편 차(sd)를 확인하면 됩니다. 표준편차(sd)는 13.54 입니다. 마지막으로 데이터 가공과 결과값 확인이 끝났다면 하단의 ‘가공 데이터 저장’ 버튼을 클릭하여 결과 값을 저장해주시면 됩니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('a0f44a5c-ebc3-54bb-be97-026e26b435f3','absolute_tolerance',null,'13.54',4,0.0005) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('d70e7d95-7006-5833-816f-11eaa5ca961d','ab1e4ff9-1462-5d53-b28b-9688869eaf66','9fb1087f-f65f-5ac1-a4c0-a1867faefa91',11,'single_choice','3개의 머신러닝 모델을 다음과 같은 설정으로 학습하고, 이 중 MAE를 기준으로 가장 성능 이 높은 모델을 선택하시오. O 작업 데이터 선택 - 문항 10번의 데이터 가공을 통해 신규로 저장된 데이터 사용, 별도의 스케일링 처리 불필 요. O 학습 유형 - 본 과제 해결에 알맞은 알고리즘의 유형을 고려하여 선택 O ML 모델 선택 - Linear Regression, K Neighbors Regressor, Random Forest Regressor O Output 컬럼 - "종속 변수"를 output 컬럼으로 지정 O Input 컬럼 - 문항 3번의 정답 컬럼은 제외 컬럼으로 지정 - 문항 10번의 결측치 처리에 사용된 ''변환하기 전의 변수''는 제외 컬럼으로 지정 O Data Parameter 설정 - 종속변수의 데이터 유형은 모델 유형에 맞게 설정하고, 나머지는 초기 설정값 사용 O 모델 Parameter 설정 - 초기 설정값 사용 (1) Linear Regression (2) K Neighbors Regressor (3) Random Forest Regressor',5.33,2,array['문제 유형 판단','머신러닝','모델 평가 지표']::text[],'AI모델학습-머신러닝 메뉴로 이동합니다. 문제에서 주어진 가이드에 따라 문항10번에서 가공하고 저 장한 데이터를 ‘작업 데이터 선택’에서 선택합니다. 다음으로 ‘학습 유형’은 문항1번에서 확인했듯이 Regression(회귀)를 선택합니다. 학습에 사용할 3가지 모델(Linear Regression, K Neighbors Regressor, Random Forest Regressor)을 ‘ML 모델 선택’에서 선택합니다. 종속 변수인 ‘label_fee’를 Input 컬럼 목록에서 선택하여 위쪽 방향 화살표를 클릭하여 Output 컬럼으로 옮겨 줍니다. 문항 3번의 정답(특정 범주에 90%이상의 데이터가 몰려 있는 변수)인 ‘서비스 구분 (service_category)’ 변수와 문항 10번의 결측치 처리에 사용된 ‘변환하기 전의 변수’인 ‘잔여약정 개월수(agreement_month)’, ''할부여부(installment_yn)'', ‘ 고객등급(customer_class)’, ‘이전 달 납부금액(prev_fee)’을 각각 선택 후 아래쪽 방향 화살표를 클릭하여 제외 컬럼으로 옮겨줍니다. 나 머지 파라미터(parameter)는 기본값으로 놔두고 ‘학습 시작’ 버튼을 눌러줍니다. 조금 기다리면 우 측에 학습 결과가 나타나는데요. 여러 성능 평가 지표 중에 문항에서 제시한 MAE가 평균적으로 가 장 낮은 모델은 MAE가 가장 낮은 Random Forest Regressor입니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
