insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('d70e7d95-7006-5833-816f-11eaa5ca961d','exact','db1fb62b-9caa-550a-9efa-50443a932e4e',null,null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('c501dfb6-b90a-524d-a1de-356d3e4814f2','ab1e4ff9-1462-5d53-b28b-9688869eaf66','9fb1087f-f65f-5ac1-a4c0-a1867faefa91',12,'decimal','딥러닝 모델을 다음과 같은 설정으로 학습하고, 학습된 모델의 MSE를 작성하시오. O 작업 데이터 선택 - 문항 10번의 데이터 가공을 통해 신규로 저장된 데이터 사용, 별도의 스케일링 처리 불필 요 O Output 컬럼 - "종속 변수"를 output 컬럼으로 지정 O Input 컬럼 - 문항 3번의 정답 컬럼은 제외 컬럼으로 지정 - 문항 10번의 결측치 처리에 사용된 ''변환하기 전의 변수''는 제외 컬럼으로 지정 - 범주형 변수는 데이터 인코더를 sparse로 변경 O 컬럼 Parameter 설정 - 종속변수의 데이터 유형은 모델 유형에 맞게 설정 - 활성함수: relu, FC레이어수: 1, FC레이어크기: 128, 드롭아웃: 0, O 학습 Parameter 설정 - Epochs: 20, Batch Size: 64, 그 외 초기 설정값 사용 O 답안 작성 - 모델 학습 후 오른쪽 상단의 [모델 저장] 기능을 통해 모델을 저장하시오. - 정답은 반올림하여 소수점 네 번째 자리까지 작성하시오.',5.34,2,array['딥러닝','모델 평가 지표']::text[],'AI모델학습-딥러닝 메뉴로 이동합니다. 문제에서 주어진 가이드에 따라 문항5번에서 가공하고 저장 한 데이터를 ‘작업 데이터 선택’에서 선택합니다. 다음으로 종속 변수인 ‘label_fee’를 Input 컬럼 목 록에서 선택하여 위쪽 방향 화살표를 클릭하여 Output 컬럼으로 옮겨줍니다. 문항 3번의 정답(특정 범주에 90%이상의 데이터가 몰려 있는 변수)인 ‘서비스 구분(service_category)’ 변수와 문항 10 번의 결측치 처리에 사용된 ‘변환하기 전의 변수’인 ‘잔여약정개월수(agreement_month)’, ''할부여부 (installment_yn)'', ‘고객등급(customer_class)’, ‘이전 달 납부금액(prev_fee)’을 각각 선택 후 아 래쪽 방향 화살표를 클릭하여 제외 컬럼으로 옮겨줍니다. 다음으로 범주형 변수 3가지 (customer_level, installment_yn_IM, customer_class_IM)는 문항 가이드에 따라서 데이터 인 코더를 sparse로 설정해야 합니다. 각 범주형 변수를 클릭하고 ‘컬럼 Parameter 설정’에서 ‘데이터 인코더’를 sparse로 변경해줍니다. 이번에는 모델 종류를 확인해보겠습니다. ‘label_fee’를 선택하여 회귀모델로 설정이 되어 있는지 확인을 해야 합니다. ‘ 컬럼 Parameter 설정’에서 ‘모델 유형’이 regressor인지 확인하고 문항에서 가이드한대로 ‘활성 함수’가 relu인지도 확인을 해주셔야 합니다. 그리고 문항에서 가이드한대로 FC레이어수: 1, FC레이어크기: 128, 드롭아웃: 0으로 컬럼 Parameter 를 설정하고 ‘학습 Parameter 설정’에서 Epochs: 20, Batch Size: 64 로 설정합니다. 나머지 파라 미터(parameter)는 기본값으로 놔두고 ‘학습 시작’ 버튼을 눌러줍니다. 조금 기다리면 우측에 학습 결과가 나타납니다. 학습 로그의 가장 마지막에서 모델 성능을 확인할 수 있습니다. 여러 성능 평가 지표 중에 문항에서 제시한 MSE는 0.4780입니다. 마지막으로 오른쪽 상단의 [모델 저장] 기능을 통해 모델을 저장해주시면 됩니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('c501dfb6-b90a-524d-a1de-356d3e4814f2','absolute_tolerance',null,'0.4780',4,0.0005) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('a6d351f7-6199-5c87-b624-07cb0546a4b4','ab1e4ff9-1462-5d53-b28b-9688869eaf66','5853a7e0-6730-5369-b845-3afbea53f5db',13,'single_choice','문항 12번에서 학습한 딥러닝 모델 분석 결과, '' 납부 예정금액(label_fee)'' 예측에 영향을 주는 상위 5개의 변수에 해당하지 않는 것을 고르시오. (1) 이전 달 납부금액(prev_fee_IM) (2) 고객등급(customer_class_IM) (3) 잔여약정개월수(agreement_month_IM) (4) 부가정보1(extra_info1)',8.0,2,array['변수 영향도']::text[],'AI모델활용 메뉴로 이동합니다. ‘ 작업 데이터 선택’에서 모델 학습에 사용한 데이터 (amount_processed)를 선택하고 아래 ‘학습 모델 목록’에서는 문항12번에서 학습하고 저장한 모 델을 선택합니다. 예측에 영향을 주는 상위 5개 변수를 확인하기 위해서는 ‘변수 영향도 확인’ 기능을 사용해야 합니다. ‘변수 영향도 확인’ 버튼을 클릭하면 우측에서 그래프 형태로 ‘label_fee’ 변수의 상 위 5개 변수의 영향도를 확인할 수 있습니다. ‘부가정보1(extra_info1)이 상위 5개 변수에 해당하지 않는 변수임을 알 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
