insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('b0f62fc0-b8b7-5a00-ac59-29a6d653389e','ab1e4ff9-1462-5d53-b28b-9688869eaf66','5853a7e0-6730-5369-b845-3afbea53f5db',14,'integer','문항 12번에서 학습한 딥러닝 모델을 활용하여 다음과 같은 조건일 때의 ''납부 예정금액 (label_fee)''을 예측하시오. O 입력값 - agreement_month_IM: 18 - customer_class_IM: Gold - customer_level: A - extra_info1: 0 - extra_info2: 0 - installment_yn_IM: Y - prev_fee_IM: 48500 O 정답은 반올림하여 정수로 작성하시오.',8.0,2,array['예측 시뮬레이션']::text[],'AI모델활용 메뉴로 이동합니다. ‘ 작업 데이터 선택’에서 모델 학습에 사용한 데이터 (amount_processed)를 선택하고 아래 ‘학습 모델 목록’에서는 문항12번에서 학습하고 저장한 모 델을 선택합니다. 특정 입력값에 대해 결과값을 예측하기 위해서는 ‘시뮬레이션’ 기능을 사용해야 합 니다. ‘ 시뮬레이션’ 버튼을 클릭하면 우측에서 입력값을 기입하고 예측 결과를 확인할 수 있습니다. 문 제에서 제시한 입력값을 기재하면 ''납부 예정금액(label_fee)''의 예측값 51668을 확인할 수 있습니 다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('b0f62fc0-b8b7-5a00-ac59-29a6d653389e','exact',null,'51668',null,null) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
insert into public.questions(id,exam_id,section_id,number,type,prompt,score,difficulty,competency_tags,explanation,is_active) values('1b9c6985-be3e-5e17-96a3-6ac27dad5cc4','ab1e4ff9-1462-5d53-b28b-9688869eaf66','5853a7e0-6730-5369-b845-3afbea53f5db',15,'decimal','문항 12번에서 학습한 딥러닝 모델을 고도화할 예정입니다. "모델의 과적합을 방지하기 위 한 파라미터"인 드롭아웃을 0.5로 설정하여 MSE를 개선하고 그 값을 작성하시오. O 변경한 파라미터 이외의 학습 변수 및 파라미터(학습/컬럼 parameter)는 모두 12번 모델 학습의 설정과 동일합니다. O 정답은 반올림하여 소수점 네 번째 자리까지 작성하시오.',8.0,2,array['성능 개선']::text[],'성능 개선의 경우 여러 가지 경우의 향상 방법이 존재합니다. 본 해설에서는 대표적인 성능 향상 방 법 중 하나인 모델의 파라미터 변경을 사용하여 진행해보려고 합니다. AI 모델학습-딥러닝 메뉴로 이 동합니다. " "모델의 과적합을 방지하기 위한 파라미터"인 드롭아웃을 0.5로 지정하고 나머지 설정은 문항 12번과 동일하게 지정해줍니다. 학습 로그의 가장 마지막에서 모델 성능을 확인할 수 있습니다. MSE는 오차이기 때문에 값이 작으면 작을수록 성능이 좋은 모델이고 0.4775이 나와 성능이 개선 된 모델임을 알 수 있습니다.',true) on conflict(exam_id,number) do update set prompt=excluded.prompt,explanation=excluded.explanation;
insert into public.answer_keys(question_id,grading_type,correct_choice_id,correct_value,decimal_places,tolerance) values('1b9c6985-be3e-5e17-96a3-6ac27dad5cc4','absolute_tolerance',null,'0.4775',4,0.0005) on conflict(question_id) do update set grading_type=excluded.grading_type,correct_choice_id=excluded.correct_choice_id,correct_value=excluded.correct_value,decimal_places=excluded.decimal_places,tolerance=excluded.tolerance;
